213			return PackageDelivery{}, fmt.Errorf("%w: exchange id is required", ErrInvalidArgument)
214		}
215	
216		var out PackageDelivery
217		err := s.view(func(snap *snapshot) error {
218			// 核对时刻在进入临界区、真正开始核对本次取包权限时才取样：请求发出后
219			// 若因等待其他操作而排队，等待时间不能延长绑定授权的有效判断——
