335		}
336		if len(res.Records) != 1 || res.Records[0].RecordID != f.rid {
337			t.Fatalf("read records = %+v, want record %q", res.Records, f.rid)
338		}
339	
340		// 关闭重开后仍只有那一条授权归属于该接收方，标识逐字相同。
341		s = reopenStore(t, s, dir, clk)
342		t.Cleanup(func() { _ = s.Close() })
343		auths, err = s.ListAuthorizations(doc, f.pid, explicit)
344		if err != nil {
345			t.Fatal(err)
346		}
347		if len(auths) != 1 || auths[0].ID != a1.ID || auths[0].ReceiverID != explicit {
348			t.Fatalf("authorizations after reopen = %+v, want only %q", auths, explicit)
349		}
350		all, err := s.ListAuthorizations(doc, f.pid, "")
351		if err != nil {
352			t.Fatal(err)
353		}
354		if len(all) != 1 {
355			t.Fatalf("extra authorizations appeared after reopen: %+v", all)
356		}
357	}
